from typing import List, Dict, Any, Optional, Callable
from leann.api import SearchResult
from leann.metadata_filter import MetadataFilterEngine
from collections import defaultdict

def aggregate_search_results(
    search_results: List[SearchResult],
    group_by_field: str,
    aggregation_funcs: Optional[Dict[str, Callable]] = None
) -> Dict[str, Dict[str, Any]]:
    """Aggregate search results by a metadata field with optional statistics.

    Args:
        search_results: List of SearchResult objects to aggregate
        group_by_field: Metadata field name to group by
        aggregation_funcs: Optional dictionary mapping field_name to aggregation function.
            Example: {"score": max, "count": len}
            If None, defaults to count and average score per group

    Returns:
        Dictionary mapping group_value to aggregated statistics
        Example: {"tech": {"count": 5, "avg_score": 0.85, "max_score": 0.95}}
    """
    # Initialize grouped results dictionary
    grouped_results: Dict[str, List[SearchResult]] = defaultdict(list)

    # Group results by the specified metadata field
    for result in search_results:
        # Try to get the field value from metadata
        field_value = result.metadata.get(group_by_field)

        # Handle missing field values - assign to 'unknown' group
        if field_value is None:
            field_value = "unknown"

        # Convert field value to string for consistent dictionary keys
        group_key = str(field_value)
        grouped_results[group_key].append(result)

    # Calculate statistics for each group
    aggregated_stats: Dict[str, Dict[str, Any]] = {}

    for group_value, group_results in grouped_results.items():
        stats: Dict[str, Any] = {}

        if aggregation_funcs is None:
            # Default statistics: count, average score, max score, min score
            stats["count"] = len(group_results)

            if group_results:
                scores = [r.score for r in group_results]
                stats["avg_score"] = sum(scores) / len(scores)
                stats["max_score"] = max(scores)
                stats["min_score"] = min(scores)
        else:
            # Apply custom aggregation functions
            for stat_name, agg_func in aggregation_funcs.items():
                try:
                    if stat_name == "count":
                        # For count, apply to the list itself
                        stats[stat_name] = agg_func(group_results)
                    elif stat_name == "score" or "score" in stat_name:
                        # For score-related aggregations, extract scores
                        scores = [r.score for r in group_results]
                        stats[stat_name] = agg_func(scores) if scores else 0
                    else:
                        # For other fields, try to extract from metadata
                        values = []
                        for r in group_results:
                            val = r.metadata.get(stat_name)
                            if val is not None:
                                values.append(val)

                        if values:
                            stats[stat_name] = agg_func(values)
                        else:
                            stats[stat_name] = None
                except Exception:
                    # If aggregation fails, set to None
                    stats[stat_name] = None

        aggregated_stats[group_value] = stats

    return aggregated_stats

